insert into public.toasts (author, occasion, title, body) values
(null, 'supra', 'ღმერთის სადღეგრძელო', 'პირველი ჭიქა ღმერთს ეკუთვნის, რომელმაც ეს დღე გვაჩუქა და ერთ სუფრასთან შემოგვკრიბა. დაგვიფაროს ყველანი, მშვიდობა მოგვცეს და ერთმანეთის სიყვარული არ მოგვაკლოს. გაგვიმარჯოს!'),
(null, 'homeland', 'სამშობლოს სადღეგრძელო', 'საქართველო პატარა ქვეყანაა, მაგრამ მისი სიყვარული გულში არ გვეტევა. სადაც არ უნდა ვიყოთ, ის ყოველთვის ჩვენთანაა. გაუმარჯოს ჩვენს სამშობლოს, მის მთებს, ზღვას, ვენახებს და ხალხს!'),
(null, 'supra', 'მშვიდობის სადღეგრძელო', 'ყველაფერი, რაც ამ სუფრაზე გვიდგას, მშვიდობის ნაყოფია. ვისურვოთ, რომ ჩვენს შვილებს ომის ხმა მხოლოდ წიგნებიდან ესმოდეთ და ყოველი დილა მშვიდად გათენდეს. მშვიდობას გაუმარჯოს!'),
(null, 'supra', 'მასპინძლის სადღეგრძელო', 'ამ სუფრის ყოველ ლუკმაში და ყოველ ჭიქაში მასპინძლის გული დევს. ღმერთმა ნუ მოუშალოს ეს სახლი, ბარაქა და სიხარული არ მოაკლოს. გაუმარჯოს ამ ოჯახს და მის მასპინძელს!'),
(null, 'parents', 'მშობლების სადღეგრძელო', 'ჩვენ აქ ვართ, რადგან ოდესღაც ვიღაცამ ღამეები გაათენა ჩვენს აკვანთან. ეს ჭიქა ჩვენი მშობლების სიცოცხლეს და ჯანმრთელობას. ღმერთმა ბევრი წელი გვამყოფოს მათ გვერდით. გაუმარჯოს ჩვენს მშობლებს!'),
(null, 'memorial', 'შენდობის სადღეგრძელო', 'ეს ჭიქა მათ ეკუთვნის, ვინც ჩვენს სუფრას აღარ უზის, მაგრამ ჩვენში ცოცხლობს: მათ სიტყვაში, ღიმილში, ჩვენს სახელებში. ღმერთმა აცხონოს და ნათელში ამყოფოს ყველა ჩვენი წასული. საუკუნოდ იყოს მათი ხსოვნა.'),
(null, 'friends', 'მეგობრობის სადღეგრძელო', 'მეგობარი ის არის, ვისაც შენი სიხარული შენზე მეტად უხარია და შენს ჭირს ჩუმად იზიარებს. დიდი სიმდიდრეა, როცა ასეთი ადამიანები ერთ სუფრასთან სხედან. გაუმარჯოს ჩვენს მეგობრობას, ბევრ წელს ეყოს!'),
(null, 'love', 'ქალების სადღეგრძელო', 'ქალი სახლის სითბოა და სუფრის სილამაზე. მათ გარეშე არც ეს სუფრა იქნებოდა ასე გაშლილი და არც ჩვენ ვიქნებოდით ასეთები. გაუმარჯოს დედებს, დებს, მეუღლეებს და ყველა ქალს, ვინც ამ სამყაროს ალამაზებს!'),
(null, 'love', 'სიყვარულის სადღეგრძელო', 'სიყვარული ის ძალაა, რომლითაც ეს სამყარო ჯერ კიდევ დგას. ვისაც უყვარს, ეს ჭიქა მათ სიყვარულს. ვისაც ჯერ არ უპოვია, მალე იპოვოს. გაუმარჯოს სიყვარულს!'),
(null, 'kids', 'ბავშვების სადღეგრძელო', 'ბავშვები მხოლოდ ჩვენი მომავალი არ არიან, ისინი ახლა, ამ წუთში იზრდებიან და ჩვენგან სწავლობენ. ვიყოთ ისეთები, რომლებითაც იამაყებენ. გაუმარჯოს ჩვენს ბავშვებს, ჯანმრთელები და ბედნიერები გაიზარდონ!'),
(null, 'guests', 'სტუმრის სადღეგრძელო', 'სტუმარი ღვთისაა, და დღეს ეს სახლი ორმაგად კურთხეულია. მადლობა, რომ გზა ჩვენკენ გამოგიყვანიათ. ჩვენი კარი ყოველთვის ღიაა თქვენთვის. გაუმარჯოს ჩვენს ძვირფას სტუმრებს!'),
(null, 'wedding', 'ნეფე-პატარძლის სადღეგრძელო', 'დღეს ორი გზა ერთ გზად იქცა. ვუსურვოთ ახალ წყვილს, რომ ერთმანეთს ყოველ დილას ისე უყურებდნენ, როგორც დღეს, და სიხარული ყოველთვის გაორმაგებული ჰქონდეთ. ბედნიერად დაბერდით! გაუმარჯოს ნეფე-პატარძალს!'),
(null, 'christening', 'ნათლობის სადღეგრძელო', 'დღეს პატარამ სახელი და ნათლია შეიძინა, ჩვენ კი ახალი ნათესავი. ღმერთმა ჯანმრთელი, კეთილი და ბედნიერი გაზარდოს, ნათლია კი ყოველთვის მის გვერდით იყოს. გაუმარჯოს ნათლულს და ნათლიას!'),
(null, 'birthday', 'დაბადების დღის სადღეგრძელო', 'დღეს ის დღეა, როცა ამ სამყაროს ერთი კარგი ადამიანი შეემატა. ვუსურვოთ, რომ ყოველი ახალი წელი წინაზე უკეთესი იყოს, ოცნებები აუხდეს და გვერდით ყოველთვის ახლობლები ჰყავდეს. გაუმარჯოს იუბილარს!'),
(null, 'friends', 'ერთმანეთის სადღეგრძელო', 'ბოლო ჭიქა ჩვენ, ამ სუფრასთან მსხდომებს. ხვალ ყველა თავის საქმეს დავუბრუნდებით, მაგრამ ეს საღამო ჩვენთან დარჩება. მალე ისევ ერთად შევიკრიბოთ, ასე მხიარულად და ჯანმრთელად. გაგვიმარჯოს!');
